mapper.update:
update p_merchant_asset_flow
mid = #{mid}, uid = #{uid}, scene = #{scene}, symbol = #{symbol}, day = #{day}, base_amount = #{baseAmount}, currency = #{currency}, exchange_rate = #{exchangeRate}, balance = #{balance}, frozen = #{frozen}, relate_id = #{relateId}, relate_memo = #{relateMemo}, pay_uid = #{payUid}, pay_channel = #{payChannel}, clear_day = #{clearDay}, begin_balance = #{beginBalance}, begin_frozen = #{beginFrozen}, payer = #{payer}, payment = #{payment}, refunded = #{refunded}, refund_at = #{refundAt}, memo = #{memo}, create_at = #{createAt}, create_time = #{createTime},
where id = #{id}

mapper.select:
, (
WITH RECURSIVE cte AS (
select 0 as n, u.* from u_member u  join u_login ul on u.id = ul.uid and ul.type in (3) 

    and u.deleted = 0
     and u.id = #{uid}
     and ul.account  = #{account} 
     and u.pid = #{pid}

union all
select  n+1,e.* from u_member e inner join `cte` c on e.pid = c.id and e.deleted = 0
) select distinct id, pid, n from `cte`
) b

     and a.mid = #{mid}
    and a.uid = b.id
     and a.scene = #{scene}
     and a.day between #{params.beginDay} and #{params.endDay}
     and a.currency = #{currency}
     and a.relate_id = #{relateId}
     and a.refunded = #{refunded}

order by b.n, b.id

