SELECT a.DAY, IFNULL(SUM(CASE WHEN a.scene = '0202' AND a.refunded = 0 THEN a.balance END),0) pay, IFNULL(SUM(CASE WHEN a.scene = '0202' AND a.refunded = 1 THEN a.balance END),0) payRefund, IFNULL(SUM(CASE WHEN a.scene = '0103' AND a.refunded = 0 AND a.currency = 'USDT' THEN a.actual_amount END),0) withdrawUsdt, IFNULL(SUM(CASE WHEN a.scene = '0103' AND a.refunded = 0 AND a.currency = 'USDT' THEN a.prize_amount END),0) withdrawPrizeUsdt, IFNULL(SUM(CASE WHEN a.scene = '0103' AND a.refunded = 1 AND a.currency = 'USDT' THEN a.balance END),0) withdrawRefundUsdt, IFNULL(SUM(CASE WHEN a.scene = '0103' AND a.refunded = 0 AND a.currency = 'CNY' THEN a.balance END),0) withdrawOfCny, IFNULL(SUM(CASE WHEN a.scene = '0103' AND a.refunded = 1 AND a.currency = 'CNY' THEN a.balance END),0) withdrawRefundOfCny, IFNULL(SUM(CASE WHEN a.scene = '0103' AND a.refunded = 0 AND a.currency = 'CNY' THEN a.actual_amount END),0) withdrawCny, IFNULL(SUM(CASE WHEN a.scene = '0103' AND a.refunded = 0 AND a.currency = 'CNY' THEN a.prize_amount END),0) withdrawPrizeCny, IFNULL(SUM(CASE WHEN a.scene = '0103' AND a.refunded = 1 AND a.currency = 'CNY' THEN a.actual_amount END),0) withdrawRefundCny FROM p_merchant_asset_flow a left join u_login l on a.uid = l.uid and l.type = 1 , u_member u
and a.uid = u.id and l.account = #{account} and a.uid = #{uid} and a.mid = #{mid} and a.`day` between #{params.beginDay} and #{params.endDay}
group by a.day order by a.day desc

SELECT a.DAY, IFNULL(SUM(CASE WHEN a.scene = '0202' AND a.refunded = 0 THEN a.balance END),0) pay, IFNULL(SUM(CASE WHEN a.scene = '0202' AND a.refunded = 1 THEN a.balance END),0) payRefund, IFNULL(SUM(CASE WHEN a.scene = '0103' AND a.refunded = 0 AND a.currency = 'USDT' THEN a.actual_amount END),0) withdrawUsdt, IFNULL(SUM(CASE WHEN a.scene = '0103' AND a.refunded = 0 AND a.currency = 'USDT' THEN a.prize_amount END),0) withdrawPrizeUsdt, IFNULL(SUM(CASE WHEN a.scene = '0103' AND a.refunded = 1 AND a.currency = 'USDT' THEN a.balance END),0) withdrawRefundUsdt, IFNULL(SUM(CASE WHEN a.scene = '0103' AND a.refunded = 0 AND a.currency = 'CNY' THEN a.balance END),0) withdrawOfCny, IFNULL(SUM(CASE WHEN a.scene = '0103' AND a.refunded = 1 AND a.currency = 'CNY' THEN a.balance END),0) withdrawRefundOfCny, IFNULL(SUM(CASE WHEN a.scene = '0103' AND a.refunded = 0 AND a.currency = 'CNY' THEN a.actual_amount END),0) withdrawCny, IFNULL(SUM(CASE WHEN a.scene = '0103' AND a.refunded = 0 AND a.currency = 'CNY' THEN a.prize_amount END),0) withdrawPrizeCny, IFNULL(SUM(CASE WHEN a.scene = '0103' AND a.refunded = 1 AND a.currency = 'CNY' THEN a.actual_amount END),0) withdrawRefundCny FROM p_merchant_asset_flow a, ( WITH RECURSIVE cte AS ( select 0 as n, u.* from u_member u join u_login ul on u.id = ul.uid and ul.type in (3)
and u.deleted = 0 and u.id = #{uid} and ul.account = #{account} and u.pid = #{pid}
union all select n+1,e.* from u_member e inner join `cte` c on e.pid = c.id and e.deleted = 0 ) select distinct id, pid, n from `cte` ) b
and a.uid = b.id and a.mid = #{mid} and a.`day` between #{params.beginDay} and #{params.endDay}
group by a.day order by a.day desc
